//
// fold-chat-sandbox.js runs what the machine door returned in a sandboxed iframe and watches what it
// does. On the web it gives the iframe `srcdoc`. In an extension an srcdoc frame inherits the page's
// CSP (script-src 'self'), so the artifact's own inline script would never run and the observer would
// report a perfectly good page as "never finished loading".
//
// The manifest therefore lists THIS page under `sandbox.pages`: it is served with its own, relaxed
// CSP (inline script allowed — that is the artifact's code, not ours), in an opaque origin with no
// chrome.* APIs, no extension storage, no host permissions. The parent hands it the HTML once it has
// loaded; this page writes it as its document and the probe inside it reports back to the parent by
// postMessage exactly as it does from an srcdoc frame.

window.addEventListener("message", function onMessage(e) {
  if (e.source !== window.parent) return;               // only the page that embedded us
  var d = e.data;
  if (!d || typeof d.html !== "string" || !d.__foldsandbox) return;
  window.removeEventListener("message", onMessage);     // one artifact per frame
  document.open();
  document.write(d.html);
  document.close();
});
"}
